events.command:
# Compute percentage using awk
tail -n +2 /workspace/treeness_output.txt | awk -F'\t' '
BEGIN { total_processed = 0; above = 0 }
{ total_processed++; if ($5+0 > 0.06) above++ }
END {
  total_genes = 255
  printf "Processed: %d\n", total_processed
  printf "Above 0.06: %d\n", above
  printf "Total fungal genes: %d\n", total_genes
  printf "Percentage: %.2f%%\n", above * 100.0 / total_genes
}'

